\@gobble{nota}\mbox{}
\begin{enumerate}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{nota1}
The exponential map identifies $\mathbb{R}/2\pi\mathbb{Z}$ with $S^1$ by $\theta\mathchoice{\longmapsto}{\mapsto}{\mapsto}{\mapsto}\mathrm{e}^{\texttt{i}\theta}$ (with $\texttt{i}=\sqrt{-1}$). We~will abuse notation by writing $\theta\in S^1$.
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{nota2}
Let $Z$ be a topological space and $V$ be an open subset of $Z$. For a sheaf~$\mathcal{F}$ on~$Z$, the notation $\mathcal{F}_V$ refers to the sheaf on $Z$ obtained by restricting $\mathcal{F}$ to the open set~$V$ and then extend it by zero to $Z$.
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
The base ring $A$ is either $\mathbb{Z}$ or a field, usually $\mathbb{Q}$ or $\mathbb{C}$. For most arguments, a commutative ring with finite global homological dimension would suffice (see\kern.3em\cite[Conv.\,3.0]{K-S90}).
\end{enumerate}

\@gobble{choice:Crho}\mbox{}
\begin{itemize}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
We fix a projectivization $f_X:X\rightarrow\mathbb{A}^{\!1}$ of $f$ such that the complement $H=X\smallsetminus U$ is a divisor with normal crossings whose irreducible components are smooth. We~denote by $j:U\mathrel{\lhook\joinrel\rightarrow} X$ the open inclusion.
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
We fix a finite subset $C\subset\mathbb{A}^{\!1}$ such that the map $f_X:X\smallsetminus f_X^{-1}(C)\rightarrow\mathbb{A}^{\!1}\smallsetminus C$ is smooth and, for each $x\in H\smallsetminus f_X^{-1}(C)$, the germ $f_{X,x}:((X,H),x)\rightarrow(\mathbb{C},f(x))$ is isomorphic to the projection
\[
(\mathbb{C},f(x))\times ((\mathbb{C}^{d-1},0),(H',0))\rightarrow(\mathbb{C},f(x)),
\]
where $H'$ is a union of coordinate hyperplanes of $\mathbb{C}^{d-1}$.
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
We fix $\rho>0$ large enough so that the interior $\mathaccent"7017\Delta_\rho$ of a closed disc $\Delta_\rho$ in~$\mathbb{A}^{\!1}$ of radius $\rho>0$ contains $C$.
\end{itemize}

\@gobble{lem:vanishing}
Let $\mathcal{F}$ be a perverse sheaf on $\mathbb{A}^{\!1}$ with singular points in $C$ and let $B\subset\mathbb{A}^{\!1}$ be a subset homeomorphic to a product $[a,b)\times[c,d]$, such that $C\cap\partial B=\varnothing$. Then
\begin{enumerate}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
$\mathrm{H}^k_\mathrm{c}(B,\mathcal{F})=0$ for $k\neq0$,
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
$\mathrm{H}^0_\mathrm{c}(B,\mathcal{F})=0$ if $C\cap B=\varnothing$.\hfill\hbox{\rlap{$\sqcap$}$\sqcup$}
\end{enumerate}

\@gobble{cor:Ufpush}
We have natural isomorphisms
\begin{align*}
\mathrm{H}^r(U,f;A)&\simeq \mathrm{H}^0_\mathrm{c}(\widetilde\Delta_\rho;\raisebox{6pt}{$\scriptscriptstyle\mathrm{p}$}\!R^{r-d}f_*({}^{\scriptscriptstyle\mathrm{p}}\!A_U)),\\
\mathrm{H}^r_\mathrm{c}(U,f;A)&\simeq \mathrm{H}^0_\mathrm{c}(\widetilde\Delta_\rho;\raisebox{6pt}{$\scriptscriptstyle\mathrm{p}$}\!R^{r-d}f_!({}^{\scriptscriptstyle\mathrm{p}}\!A_U)).
\end{align*}

\@gobble{def:coHUf}
The singular cohomologies in degree $r$ of the pair $(U,f)$ are defined as singular cohomology spaces with compact support:
\begin{align*}
\mathrm{H}^r(U,f;A):=\mathrm{H}^r_\mathrm{c}(\widetilde U_\mathrm{mod}\,;A)\quad\text{and}\quad\mathrm{H}^r_{\mathrm{c}}(U,f;A):=\mathrm{H}^r_\mathrm{c}(\widetilde U_\mathrm{rd};A).
\end{align*}

We will consider the perverse $(r-d)$-cohomology of the pushforward complex $\boldsymbol{R} f_*A_U$ and $\boldsymbol{R} f_!A_U$. At this point, using perverse cohomology sheaves instead of ordinary cohomology sheaves will simplify many arguments.

From Corollary \ref{cor:pervexact} we deduce the expressions
\begin{equation}\@gobble{eq:Ufpush}
\begin{aligned}
\mathrm{H}^r(U,f;A)&\simeq \mathrm{H}^0_\mathrm{c}({\widetilde{\mathbb{A}}}^{\!1}_\mathrm{mod}\,;\boldsymbol{R}\alpha_*\raisebox{6pt}{$\scriptscriptstyle\mathrm{p}$}\!R^{r-d}f_*({}^{\scriptscriptstyle\mathrm{p}}\!A_U)),\\
\mathrm{H}^r_\mathrm{c}(U,f;A)&\simeq \mathrm{H}^0_\mathrm{c}({\widetilde{\mathbb{A}}}^{\!1}_\mathrm{mod}\,;\boldsymbol{R}\alpha_*\raisebox{6pt}{$\scriptscriptstyle\mathrm{p}$}\!R^{r-d}f_!({}^{\scriptscriptstyle\mathrm{p}}\!A_U)),
\end{aligned}
\end{equation}
which can be identified with those of Corollary \ref{cor:Ufpush}, proving thereby Proposition~\ref{prop:coHUf}.

\@gobble{prop:HUfphifiltration}
Both $\mathrm{H}^r(U,f;A)$ and $\mathrm{H}^r_{\mathrm{c}}(U,f;A)$ have a natural increasing filtration indexed by $\{a_1,\dots,a_\ell\}$ such that, for each $i\in\{1,\dots,\ell\}$, we have
\begin{align*}
\mathrm{gr}_{a_i}\mathrm{H}^r(U,f;A)&\simeq\mathop{\textstyle\bigoplus}\displaylimits_{\substack{c\in C\\\operatorname{Re}(c)=a_i}}\mathrm{H}^{r-1}\bigl(f_X^{-1}(c),\phi_{f_X-c}(\boldsymbol{R} j_*A_U)\bigr),
\\
\mathrm{gr}_{a_i}\mathrm{H}^r_\mathrm{c}(U,f;A)&\simeq\mathop{\textstyle\bigoplus}\displaylimits_{\substack{c\in C\\\operatorname{Re}(c)=a_i}}\mathrm{H}^{r-1}\bigl(f_X^{-1}(c),\phi_{f_X-c}(\boldsymbol{R} j_!A_U)\bigr).
\end{align*}

Let us start with a perverse sheaf $\mathcal{F}$ on $\mathbb{A}^{\!1}$ with singularities on~$C$. We~will prove that the cohomology space $\mathrm{H}^0_\mathrm{c}(\widetilde\Delta_\rho;\mathcal{F})$ has a natural increasing filtration indexed by $\{a_1,\dots,a_\ell\}$ such that
\begin{equation}\@gobble{eq:graiH0}
\mathrm{gr}_{a_i}\mathrm{H}^0_\mathrm{c}(\widetilde\Delta_\rho;\mathcal{F})\simeq{}^{\scriptscriptstyle\mathrm{p}}\mkern-1mu\phi_{c_i}\mathcal{F}\quad\forall i=1,\dots,\ell.
\end{equation}
For the sake of simplicity, we assume that each $a_i$ is the real part of a unique $c_i\in C$ (otherwise, one replaces the map $\operatorname{Re}:C\rightarrow\mathbb{R}$ by the map $\operatorname{Re}+\varepsilon\operatorname{Im}$ with $\varepsilon>0$ small). Let us decompose $\widetilde\Delta_\rho$ as $\widetilde\Delta_{\rho,<a_i}\sqcup\widetilde\Delta_{\rho,\geqslant a_i}$, denoting thereby the intersection of~$\widetilde\Delta_\rho$ with the open half-plane $\operatorname{Re}(t)<a_i$, respectively closed half-plane \hbox{$\operatorname{Re}(t)\geqslant a_i$}. These subsets have the same topology as $\widetilde\Delta_\rho$, and we have a long exact sequence of cohomology with compact support
\begin{equation}\@gobble{eq:H0exact}
\cdots\rightarrow\mathrm{H}^0_\mathrm{c}(\widetilde\Delta_{\rho,<a_i};\mathcal{F})\rightarrow\mathrm{H}^0_\mathrm{c}(\widetilde\Delta_\rho;\mathcal{F})\rightarrow\mathrm{H}^0_\mathrm{c}(\widetilde\Delta_{\rho,\geqslant a_i};\mathcal{F})\rightarrow\cdots
\end{equation}
We first claim that $\mathrm{H}^k_\mathrm{c}(\widetilde\Delta_\rho;\mathcal{F})=0$ for $k\neq0$. Indeed, from this exact sequence and by induction on $\#C$, it is enough to prove this when $\#C=1$. In such a case, if $\widetilde\Delta_c$ is a small disc centered at $c\in C$ with a closed half-circle $\delta_c$ deleted on its boundary, we have $\mathrm{H}^k_\mathrm{c}(\widetilde\Delta_c;\mathcal{F})\simeq\mathrm{H}^k_\mathrm{c}(\widetilde\Delta_\rho;\mathcal{F})$. The cohomology long exact sequence associated with the open/closed decomposition $\Delta_c=\widetilde\Delta_c\sqcup\delta_c$ is then identified with that associated with the shifted distinguished triangle of \cite[(10.87)]{M-S22}
\[
{}^{\scriptscriptstyle\mathrm{p}}\psi_c\mathcal{F}\rightarrow{}^{\scriptscriptstyle\mathrm{p}}\mkern-1mu\phi_c\mathcal{F}\rightarrow i_c^{-1}\mathcal{F}[-1]
\]
and one concludes with the property that ${}^{\scriptscriptstyle\mathrm{p}}\mkern-1mu\phi_c\mathcal{F}$ is concentrated in degree zero since it is perverse on a point $c$ (because the functor ${}^{\scriptscriptstyle\mathrm{p}}\mkern-1mu\phi_c$ is t-exact, see\kern.3em Rem.\,10.4.23 in loc.\kern3pt cit.\kern-.5pt\xspace).

It follows that \eqref{eq:H0exact} is a short exact sequence and thus $\mathrm{H}^0_\mathrm{c}(\widetilde\Delta_{\rho,<a_{i+1}};\mathcal{F})\rightarrow\mathrm{H}^0_\mathrm{c}(\widetilde\Delta_\rho;\mathcal{F})$ is an inclusion, defining a filtration by the formula $\mathrm{H}^0_\mathrm{c}(\widetilde\Delta_\rho;\mathcal{F})_{\leqslant a_i}:=\mathrm{H}^0_\mathrm{c}(\widetilde\Delta_{\rho,<a_{i+1}};\mathcal{F})$. The similar exact sequence with $\widetilde\Delta_\rho$ replaced with $\widetilde\Delta_{\rho,<a_{i+1}}$ shows that $\mathrm{gr}_{a_i}\mathrm{H}^0_\mathrm{c}(\widetilde\Delta_\rho;\mathcal{F})$ is identified with $\mathrm{H}^0_\mathrm{c}(\widetilde\Delta_{\rho, [a_i,a_{i+1})};\mathcal{F})$. The latter space is isomorphic to $\mathrm{H}^0_\mathrm{c}(\widetilde\Delta_{c_i};\mathcal{F})$, that we have already identified with ${}^{\scriptscriptstyle\mathrm{p}}\mkern-1mu\phi_{c_i}\mathcal{F}$. This concludes the proof of \eqref{eq:graiH0}.

Let us now come back to the statement of the proposition. The formulas of Corollary \ref{cor:Ufpush} lead us to consider the perverse cohomology sheaves $\mathcal{F}=\raisebox{6pt}{$\scriptscriptstyle\mathrm{p}$}\!R^{r-d}f_*({}^{\scriptscriptstyle\mathrm{p}}\!A_U)$ and $\mathcal{F}=\raisebox{6pt}{$\scriptscriptstyle\mathrm{p}$}\!R^{r-d}f_!({}^{\scriptscriptstyle\mathrm{p}}\!A_U)$, and to apply the previous result to them. However, we are faced to the problem of making the functor of \@gobble{vanishing cycles!functor}vanishing cycles commute with pushforward by $f$ when $f$ is not proper. This question is solved by Proposition \ref{prop:pushphi}.

\mbox{}\@gobble{th:kontsevichyu}
\begin{enumerate}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{th:kontsevichyu1}
The restriction to $U$ induces isomorphisms for all $r\in\mathbb{N}$:
\begin{align*}
\mathrm{H}^r_{\mathrm{dR}}(U,f)&\simeq \mathrm{H}^r\bigl(\overline X,(\Omega_f^{\raisebox{1pt}{${\scriptscriptstyle\bullet}$}},\mathrm{d}+\mathrm{d} f)\bigr),
\\
\mathrm{H}^r_{{\mathrm{dR}},\mathrm{c}}(U,f)&\simeq \mathrm{H}^r\bigl(\overline X,(\Omega_f^{\raisebox{1pt}{${\scriptscriptstyle\bullet}$}}(-D),\mathrm{d}+\mathrm{d} f)\bigr).
\end{align*}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{th:kontsevichyu2}
For each $r\in\mathbb{N}$, the natural pairing that one deduces from these identifications is nondegenerate:
\[
\mathrm{H}^r_{\mathrm{dR}}(U,f)\otimes_\mathbb{C}\mathrm{H}^{2d-r}_{{\mathrm{dR}},\mathrm{c}}(U,-f)\rightarrow \mathrm{H}^{2d}_{{\mathrm{dR}}}(\overline X)\simeq\mathbb{C}.
\]
\end{enumerate}

\@gobble{th:isoBdR}
We have natural isomorphisms
\[
\mathrm{H}^r_{\mathrm{dR}}(U,f)\simeq\mathrm{H}^r(U^\mathrm{an},f;\mathbb{Q})\otimes\mathbb{C},\quad \mathrm{H}^r_{{\mathrm{dR}},\mathrm{c}}(U,f)\simeq\mathrm{H}^r_\mathrm{c}(U^\mathrm{an},f;\mathbb{Q})\otimes\mathbb{C}
\]
which transform the de~Rham pairing into the Poincaré-Verdier duality pairing.

There exists a semi-analytic Whitney stratification $\widetilde\mathcal{S}_\rho$ of $\widetilde Z_\rho:=(\operatorname{Id}\times\widetilde f)^{-1}(\widetilde\Delta_\rho^{\leqslant\infty})\subset S^1\times X$ such that
\begin{enumerate}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
$Z_\rho:=(\operatorname{Id}\times f)^{-1}(\widetilde\Delta_\rho^{\leqslant\infty})\subset S^1\times U$ is a union of strata,
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
and for each stratum $\widetilde S$ of $\widetilde\mathcal{S}_\rho$, the map $p\circ(\operatorname{Id}\times\widetilde f)|_{\widetilde S}:\widetilde S\rightarrow S^1$ is a submersion.
\end{enumerate}

\@gobble{rem:Phiperv}\mbox{}
\begin{enumerate}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{rem:Phiperv1}
To any perverse complex $\mathcal{F}$ on $\mathbb{A}^{\!1}$ with singular set $C$, one can associate similarly a local system $\widetilde\Phi_\infty(\mathcal{F}):=p_!(q^{-1}\mathcal{F})$ on $S^1$ whose fiber at $\theta$ is $\mathrm{H}^0_\mathrm{c}(\mathrm{e}^{\texttt{i}\theta}\widetilde\Delta_\rho;\mathcal{F})$. Note that, applying the commutativity of $\boldsymbol{R} p_!$ with restriction to $\theta$ and Proposition \ref{prop:pervexact}, the higher direct images $R^kp_!(q^{-1}\mathcal{F})$ vanish for $k\geqslant1$. One recovers $\widetilde\Phi_\infty^r(U,f)$, \text{resp.}\kern.3em $\widetilde\Phi_{\infty,\mathrm{c}}^r(U,f)$, by setting $\mathcal{F}=\raisebox{6pt}{$\scriptscriptstyle\mathrm{p}$}\!R^{r-d}f_*A_U$, \text{resp.}\kern.3em $\mathcal{F}=\raisebox{6pt}{$\scriptscriptstyle\mathrm{p}$}\!R^{r-d}f_!A_U$.
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{rem:Phiperv2}
By replacing $\Delta_\rho$ by a small closed disc centered at $c\in C$, one defines similarly the local system $\widetilde{}^{\scriptscriptstyle\mathrm{p}}\mkern-1mu\phi_c\mathcal{F}$.
\end{enumerate}

\@gobble{prop:StokesF}
The family of pairs of nested subsheaves
\[
(\widetilde\Phi_\infty(\mathcal{F})_{<c},\widetilde\Phi_\infty(\mathcal{F})_{\leqslant c})_{c\in C}
\]
of the local system $\widetilde\Phi_\infty(\mathcal{F})$ satisfy the properties \ref{def:PhiStokes1}--\ref{def:PhiStokes3} of a Stokes filtration and moreover we have an identification $\mathrm{gr}_c\widetilde\Phi_\infty(\mathcal{F})\simeq\widetilde{}^{\scriptscriptstyle\mathrm{p}}\mkern-1mu\phi_c\mathcal{F}$ for each $c\in C$.

We start with Item \ref{def:PhiStokes2} of the definition of a Stokes filtration, and we compute the sheaf $\mathrm{gr}_c\widetilde\Phi_\infty(\mathcal{F})$. We set $\widetilde\Delta'_c=\widetilde\Delta_\rho^{\leqslant c}\smallsetminus \widetilde\Delta_\rho^{<c}$. (See\kern.3em Figure \ref{fig:3}.)
\begin{figure}[htb]
\centerline{\includegraphics[scale=.4]{fig3}}
\caption{Stalks of $\widetilde\Delta'_c$ and $\widetilde\Delta_c$ at $\theta$}\@gobble{fig:3}
\end{figure}

From the exact sequence of sheaves
\[
0\rightarrow A_{\Delta_{\rho,<c}}\rightarrow A_{\Delta_{\rho,\leqslant c}}\rightarrow A_{\widetilde\Delta'_c}\rightarrow0
\]
we deduce that $\mathrm{gr}_c\widetilde\Phi_\infty(\mathcal{F})\simeq p_!(\widetilde\mathcal{F}_{\widetilde\Delta'_c})$. An easy computation on the stalks together with the vanishing lemma \ref{lem:vanishing} shows that $p_!(A_{\widetilde\Delta_c\smallsetminus\widetilde\Delta'_c}\otimes\widetilde\mathcal{F})=0$, leading to the isomorphism $\mathrm{gr}_c\widetilde\Phi_\infty(\mathcal{F})\simeq\widetilde{}^{\scriptscriptstyle\mathrm{p}}\mkern-1mu\phi_c\mathcal{F}$.

For Item \ref{def:PhiStokes1}, one notices that, for $c'\neq c$, the inequality $c'<_\theta c$ is equivalent to the inclusion $\Delta_{\rho,\leqslant c',\theta}\subset \Delta_{\rho,<c,\theta}$. Since proper pushforward commutes with base change, the exact sequence
\begin{equation}\@gobble{eq:ZS}
0\rightarrow A_{\Delta_{\rho,\leqslant c'}}\rightarrow A_{\Delta_{\rho,<c}}\rightarrow A_{\Delta_{\rho,<c}\smallsetminus\Delta_{\rho,\leqslant c'}}\rightarrow0
\end{equation}
together with Lemma \ref{lem:vanishing}, leads to the exact sequence (with an obvious notation)
\begin{equation}\@gobble{eq:ZSPhi}
0\rightarrow\widetilde\Phi_\infty(\mathcal{F})_{\leqslant c',\theta}\rightarrow\widetilde\Phi_\infty(\mathcal{F})_{<c,\theta}\rightarrow\widetilde\Phi_\infty(\mathcal{F})_{c'<{\raisebox{1pt}{${\scriptscriptstyle\bullet}$}}<c,\theta}\rightarrow0,
\end{equation}
hence the filtration property.

Verification of Item \ref{def:PhiStokes3} follows by induction on $c$ with respect to the order at $\theta$.

\@gobble{def:Stokes-fillocsys}
A \@gobble{filtration!Stokes --}\@gobble{Stokes!filtration}Stokes filtration indexed by $C$ on a sheaf $\mathscr{L}$ of $A$-modules consists of a family of pairs $\mathscr{L}_{<c}\subset\mathscr{L}_{\leqslant c}\subset\mathscr{L}$ ($c\in C$) of nested subsheaves of $A$-modules such that
\begin{enumerate}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{def:Stokes1}
for each $\theta\in S^1$, the germs of $\mathscr{L}_{<c},\mathscr{L}_{\leqslant c}$ at $\theta$ satisfy
\[
c<_\theta c'\implies\mathscr{L}_{\leqslant c,\theta}\subset\mathscr{L}_{<c',\theta};
\]
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{def:Stokes2}
each quotient sheaf $\mathrm{gr}_c\mathscr{L}=\mathscr{L}_{\leqslant c}/\mathscr{L}_{<c}$ is a \@gobble{sheaf!locally constant --}\emph{locally constant sheaf} of $A$\nobreakdash-modules;
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{def:Stokes3}
in the neighborhood of each $\theta\in S^1$, there exists an isomorphism $\mathscr{L}\simeq\mathrm{gr}\mathscr{L}$ compatible with the family of nested subsheaves, where $\mathrm{gr}\mathscr{L}$ is equipped with that defined by \eqref{eq:grnested}.
\end{enumerate}

\@gobble{prop:strict}
Let $(\mathscr{L},\mathscr{L}_{\scriptscriptstyle\bullet})$ be a Stokes-filtered local system indexed by $C$.
\begin{enumerate}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{prop:strict1}
On any $C$-good open interval $I\subset S^1$, there exists a unique splitting $\mathscr{L}_{|I}\simeq\mathop{\textstyle\bigoplus}\displaylimits_c\mathrm{gr}_c\mathscr{L}_{|I}$ compatible with the Stokes filtrations.
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{prop:strict2}
Let $\lambda:(\mathscr{L},\mathscr{L}_{\scriptscriptstyle\bullet})\rightarrow(\mathscr{L}',\mathscr{L}'_{\scriptscriptstyle\bullet})$ be a morphism of Stokes-filtered local systems indexed by $C$. Then, for any $C$-good open interval $I\subset S^1$, the morphism~$\lambda_{|I}$ is graded with respect to the splittings in \eqref{prop:strict1}.
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{prop:strict3}
The category of Stokes-filtered local systems $(\mathscr{L},\mathscr{L}_{\scriptscriptstyle\bullet})$ is abelian.
\end{enumerate}

By \@gobble{Stokes!data}\emph{Stokes data} we mean the data of
\begin{itemize}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
a pair of $A$-modules $L_o,L'_o$,
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
an increasing filtration $F_{\scriptscriptstyle\bullet} L_o$, and a decreasing filtration $F^{\scriptscriptstyle\bullet} L'_o$,
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
a pair of isomorphisms $S_o^\pm:L_o\stackrel{\sim}{\longrightarrow} L'_o$ (called the Stokes isomorphisms),
\end{itemize}
subject to the following condition:
\begin{itemize}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
The image increasing filtration $S_o^+(F_{\scriptscriptstyle\bullet} L_o)$ is \emph{opposite} to the decreasing filtration $F^{\scriptscriptstyle\bullet} L'_o$, and the image decreasing filtration $(S_o^-)^{-1}(F^{\scriptscriptstyle\bullet} L'_o)$ is opposite to the increasing filtration $F_{\scriptscriptstyle\bullet} L_o$.
\end{itemize}

\@gobble{lem:nondegP}
The following properties are equivalent for a pairing $\mathsf{P}$ compatible with the Stokes filtrations:
\begin{enumerate}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{lem:nondegP1}
$\mathsf{P}$ induces an isomorphism $(\mathscr{L},\mathscr{L}_{\scriptscriptstyle\bullet})\stackrel{\sim}{\longrightarrow}\iota^{-1}(\mathscr{L}',\mathscr{L}'_{\scriptscriptstyle\bullet})^{\scriptscriptstyle\vee}$,
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{lem:nondegP2}
$\mathsf{P}$ induces an isomorphism $\mathscr{L}\stackrel{\sim}{\longrightarrow}\mathscr{L}^{\prime{\scriptscriptstyle\vee}}$,
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{lem:nondegP3}
for each $c\in C$, $\mathsf{P}_c:\mathrm{gr}_c\mathscr{L}\otimes\iota^{-1}\mathrm{gr}_c\mathscr{L}'\rightarrow A_{S^1}$ is nondegenerate.
\end{enumerate}

\@gobble{prop:hS}
Assume that $\mathsf{P}:\mathscr{L}\otimes\iota^{-1}\mathscr{L}'\rightarrow A_{S_1}$ is nondegenerate. For each $i=1,\dots,n$, let $\boldsymbol{e}_i,\boldsymbol{e}'_i$ be $A$-bases of $G_{c_i,\theta_o}, G'_{c_i,\theta'_o}$ in which the matrix of $\mathsf{P}_{\theta_o,\theta'_o}^{(i)}$ is the identity. Then the Seifert matrix of $\mathsf{P}^+_{\theta_o}$ in the basis $\boldsymbol{e}\!=\!\mathop{\textstyle\bigoplus}\displaylimits_i\boldsymbol{e}_i$ is equal to the Stokes matrix of~$S^+_{\theta_o}$ in the bases $\boldsymbol{e},\boldsymbol{e}'$.\relax\ifmmode\hbox{\rlap{$\sqcap$}$\sqcup$}\else
  {\unskip\nobreak\hfil\penalty50\hskip1em\null\nobreak\hfil\hbox{\rlap{$\sqcap$}$\sqcup$}
  \parfillskip=\z@\finalhyphendemerits=0\endgraf}\fi

\@gobble{prop:pairingF}
For $A$-perverse sheaves $\mathcal{F},\mathcal{F}'$ with a pairing $\mathsf{Q}$,
\begin{enumerate}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{prop:pairingF1}
the pairing $\mathsf{P}:\widetilde\Phi_\infty(\mathcal{F})\otimes\iota^{-1}\widetilde\Phi_\infty(\mathcal{F}')\rightarrow A_{S^1}$ is compatible with the Stokes filtrations, and the induced pairing \eqref{eq:Pc} is equal to $\mathsf{P}_c$ defined above;

\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{prop:pairingF2}
If $\mathsf{P}_c$ is nondegenerate for each $c\in C$, then each $\widetilde{}^{\scriptscriptstyle\mathrm{p}}\mkern-1mu\phi_c(\mathcal{F}),\widetilde{}^{\scriptscriptstyle\mathrm{p}}\mkern-1mu\phi_c(\mathcal{F}')$, and thus $\widetilde\Phi_\infty(\mathcal{F}),\widetilde\Phi_\infty(\mathcal{F}')$, are $A$-free, and $\mathsf{P}$ is nondegenerate;

\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{prop:pairingF3}
if $\mathsf{Q}$ is nondegenerate, then $\mathcal{F}$ and $\mathcal{F}'$ are strongly perverse, $\widetilde\Phi_\infty(\mathcal{F}),\widetilde\Phi_\infty(\mathcal{F}')$ and each $\widetilde{}^{\scriptscriptstyle\mathrm{p}}\mkern-1mu\phi_c(\mathcal{F}),\widetilde{}^{\scriptscriptstyle\mathrm{p}}\mkern-1mu\phi_c(\mathcal{F}')$ are $A$-free, $\mathsf{P}$ and each $\mathsf{P}_c$ are nondegenerate.
\end{enumerate}

For the first point, we have to show that, for each $c,\theta$, the pairing $\mathsf{P}$ induces zero on $\widetilde\Phi_\infty(\mathcal{F})_{\leqslant c,\theta}\otimes\widetilde\Phi_\infty(\mathcal{F}')_{<c,\theta'}$ and on $\widetilde\Phi_\infty(\mathcal{F})_{<c,\theta}\otimes\widetilde\Phi_\infty(\mathcal{F}')_{\leqslant c,\theta'}$. But this is clear since, in the first case for example,
\begin{itemize}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
we can compute $\widetilde\Phi_\infty(\mathcal{F})_{<c,\theta'}$ with the set $\widetilde\Delta_{\rho,\theta'}^{<c+\varepsilon\mathrm{e}^{\texttt{i}\theta}}$, according to Lemma \ref{lem:vanishing},
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax
the sets $\widetilde\Delta_{\rho,\theta}^{\leqslant c}$ and $\widetilde\Delta_{\rho,\theta'}^{<c+\varepsilon\mathrm{e}^{\texttt{i}\theta}}$ do not intersect.
\end{itemize}
The identification of both definitions of $\mathsf{P}_c$ are then clear.

The second and third points are consequences of the results already obtained.

\mbox{}\@gobble{th:kontsevichyuu}
\begin{enumerate}
\par\setbox0=\hbox{--\,--\,--\enspace} 
                  \hangindent\wd0\relax\@gobble{th:kontsevichyuu1}
Restriction to $U$ induces isomorphisms of $\mathbb{C}[u,u^{-1}]$-modules with a compatible action of $\partial_u$, for all $r\in\mathbb{N}$:
\begin{align*}
\mathrm{H}^r_{\mathrm{dR}}(U,f/u)&\simeq \mathrm{H}^r\bigl(\overline X,(\Omega_f^{\raisebox{1pt}{${\scriptscriptstyle\bullet}$}}[u,u^{-1}],\mathrm{d}+\mathrm{d} f/u)\bigr),
\\
